This is a complete, single-file 3D "Infinite Runner" game. I have used **Three.js** via CDN to handle the 3D rendering.

### How to Play:
1. Save the code below as an `.html` file (e.g., `game.html`).
2. Open it in any modern web browser.
3. **Controls**: Use the **Left and Right Arrow Keys** (or **A and D**) to dodge the incoming red blocks.
4. The game gets faster as your score increases.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Neon Runner</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #000; font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; }
        canvas { display: block; }
        #ui {
            position: absolute;
            top: 20px;
            left: 20px;
            color: #0ff;
            font-size: 24px;
            text-shadow: 0 0 10px #0ff;
            pointer-events: none;
        }
        #overlay {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            background: rgba(0, 0, 0, 0.8);
            color: white;
            z-index: 10;
        }
        button {
            padding: 15px 30px;
            font-size: 20px;
            background: #0ff;
            border: none;
            cursor: pointer;
            border-radius: 5px;
            margin-top: 20px;
            transition: transform 0.2s;
        }
        button:hover { transform: scale(1.1); }
        h1 { font-size: 48px; margin: 0; color: #0ff; text-shadow: 0 0 20px #0ff; }
    </style>
</head>
<body>

    <div id="ui">Score: <span id="score">0</span></div>

    <div id="overlay">
        <h1 id="title">NEON RUNNER</h1>
        <p id="finalScore"></p>
        <button id="startBtn">START GAME</button>
    </div>

    <!-- Load Three.js from CDN -->
    <script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>

    <script>
        // Game Constants & Variables
        let scene, camera, renderer, player, floor;
        let obstacles = [];
        let score = 0;
        let gameActive = false;
        let speed = 0.4;
        let moveLeft = false;
        let moveRight = false;
        const clock = new THREE.Clock();

        const scoreElement = document.getElementById('score');
        const overlay = document.getElementById('overlay');
        const startBtn = document.getElementById('startBtn');
        const title = document.getElementById('title');
        const finalScoreText = document.getElementById('finalScore');

        init();
        animate();

        function init() {
            // 1. Scene Setup
            scene = new THREE.Scene();
            scene.background = new THREE.Color(0x050505);
            scene.fog = new THREE.Fog(0x050505, 10, 50);

            // 2. Camera
            camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
            camera.position.set(0, 2, 5);
            camera.lookAt(0, 0, 0);

            // 3. Renderer
            renderer = new THREE.WebGLRenderer({ antialias: true });
            renderer.setSize(window.innerWidth, window.innerHeight);
            renderer.setPixelRatio(window.devicePixelRatio);
            document.body.appendChild(renderer.domElement);

            // 4. Lights
            const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
            scene.add(ambientLight);

            const pointLight = new THREE.PointLight(0x00ffff, 1, 100);
            pointLight.position.set(0, 5, 2);
            scene.add(pointLight);

            // 5. Floor
            const floorGeo = new THREE.PlaneGeometry(10, 1000);
            const floorMat = new THREE.MeshPhongMaterial({ 
                color: 0x111111, 
                emissive: 0x001122,
                side: THREE.DoubleSide 
            });
            floor = new THREE.Mesh(floorGeo, floorMat);
            floor.rotation.x = Math.PI / 2;
            scene.add(floor);

            // Grid Helper for "Neon" look
            const grid = new THREE.GridHelper(1000, 100, 0x00ffff, 0x222222);
            grid.rotation.x = 0;
            grid.position.y = 0.05;
            scene.add(grid);

            // 6. Player
            const playerGeo = new THREE.BoxGeometry(1, 1, 1);
            const playerMat = new THREE.MeshPhongMaterial({ color: 0x00ffff, emissive: 0x00ffff });
            player = new THREE.Mesh(playerGeo, playerMat);
            player.position.y = 0.5;
            scene.add(player);

            // Event Listeners
            window.addEventListener('keydown', (e) => {
                if (e.key === 'ArrowLeft' || e.key === 'a') moveLeft = true;
                if (e.key === 'ArrowRight' || e.key === 'd') moveRight = true;
            });
            window.addEventListener('keyup', (e) => {
                if (e.key === 'ArrowLeft' || e.key === 'a') moveLeft = false;
                if (e.key === 'ArrowRight' || e.key === 'd') moveRight = false;
            });
            window.addEventListener('resize', onWindowResize);
            startBtn.addEventListener('click', startGame);
        }

        function startGame() {
            // Reset Game State
            score = 0;
            speed = 0.4;
            gameActive = true;
            scoreElement.innerText = score;
            overlay.style.display = 'none';

            // Clear old obstacles
            obstacles.forEach(obj => scene.remove(obj));
            obstacles = [];

            // Reset player position
            player.position.x = 0;
        }

        function gameOver() {
            gameActive = false;
            overlay.style.display = 'flex';
            title.innerText = "GAME OVER";
            finalScoreText.innerText = "Final Score: " + Math.floor(score);
            startBtn.innerText = "TRY AGAIN";
        }

        function spawnObstacle() {
            if (Math.random() < 0.05) { // Spawn rate
                const geo = new THREE.BoxGeometry(1.5, 1.5, 1.5);
                const mat = new THREE.MeshPhongMaterial({ color: 0xff0044, emissive: 0xff0000 });
                const obs = new THREE.Mesh(geo, mat);

                // Random position on the x-axis
                obs.position.x = (Math.random() - 0.5) * 8;
                obs.position.y = 0.75;
                obs.position.z = -40;

                scene.add(obs);
                obstacles.push(obs);
            }
        }

        function onWindowResize() {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        }

        function animate() {
            requestAnimationFrame(animate);

            if (gameActive) {
                score += 0.1;
                scoreElement.innerText = Math.floor(score);

                // Increase difficulty
                speed += 0.0001;

                // Player Movement
                if (moveLeft && player.position.x > -4.5) {
                    player.position.x -= 0.15;
                }
                if (moveRight && player.position.x < 4.5) {
                    player.position.x += 0.15;
                }

                // Obstacle logic
                spawnObstacle();
                for (let i = obstacles.length - 1; i >= 0; i--) {
                    let obs = obstacles[i];
                    obs.position.z += speed;

                    // Collision Detection (AABB-ish)
                    const dx = player.position.x - obs.position.x;
                    const dz = player.position.z - obs.position.z;
                    const distance = Math.sqrt(dx*dx + dz*dz);

                    if (distance < 1.2) {
                        gameOver();
                    }

                    // Remove off-screen obstacles
                    if (obs.position.z > 10) {
                        scene.remove(obs);
                        obstacles.splice(i, 1);
                    }
                }

                // Visual effects: make the grid/floor move slightly
                floor.position.z += speed;
                if (floor.position.z > 100) floor.position.z = 0;
            }

            renderer.render(scene, camera);
        }
    </script>
</body>
</html>
```

